contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool callAsOwner) public payable {
        c = C(address(c));

        bool reverted;

        if (callAsOwner) {
            c.sudicideAnyone();
            reverted = false;
        } else {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(callAsOwner ? !reverted : reverted);
    }

    receive() external payable {}
}

